from pathlib import Path
import subprocess
import base64

BASE = "fd5ee4d"
CRAFTING = Path("app/(portal)/crafting/crafting-workbench.tsx")
UI = Path("components/sepulchria/sep-ui.tsx")

def dec(s):
    return base64.b64decode(s).decode("utf-8")

def git_show(path):
    git_path = Path(path).as_posix()
    result = subprocess.run(
        ["git", "show", f"{BASE}:{git_path}"],
        check=True,
        capture_output=True,
        text=True,
        encoding="utf-8",
    )
    return result.stdout

crafting = git_show(CRAFTING)

for old_b64, new_b64, label in [('aW1wb3J0IHsgdXNlUG9ydGFsU2tpbiB9IGZyb20gIkAvY29tcG9uZW50cy9wb3J0YWwvcG9ydGFsLXNraW4tcHJvdmlkZXIiOwppbXBvcnQgeyBmb3JtYXRSZW1uYW50cyB9IGZyb20gIkAvbGliL2Vjb25vbXkvY3VycmVuY3kiOw==', '', 'imports'), ('', 'ICAgICAgICAgICAgPFNlcEJhZGdlCiAgICAgICAgICAgICAgYWNjZW50PXtjcmFmdGluZ0FjY2VudH0KICAgICAgICAgICAgICBjbGFzc05hbWU9ImZvbnQtc2VyaWYgdGV4dC14cyB0cmFja2luZy1ub3JtYWwiCiAgICAgICAgICAgID4KICAgICAgICAgICAgICB7cmVjaXBlcy5sZW5ndGh9CiAgICAgICAgICAgIDwvU2VwQmFkZ2U+', 'recipe count badge'), ('', '', 'notice'), ('', '', 'secondary button'), ('', '', 'primary button'), ('', '', 'icon button'), ('', '', 'quality badge')]:
    old = dec(old_b64)
    new = dec(new_b64)
    if old not in crafting:
        raise SystemExit(f"Could not find expected {label} block in {BASE}.")
    crafting = crafting.replace(old, new, 1)

for marker in [
    "await craftRecipeAction(",
    "setCraftedReveal({",
    "router.refresh();",
    'url("/pattern/wooden.png")',
    'url(\\"/pattern/parchment.png\\")',
    'url(\\"/pattern/sparkle.gif\\")',
    "opacity-10",
]:
    if marker not in crafting:
        raise SystemExit(f"Safety marker missing after patch: {marker}")

UI.parent.mkdir(parents=True, exist_ok=True)
UI.write_text(dec(''), encoding="utf-8")
CRAFTING.write_text(crafting, encoding="utf-8")

print("SUCCESS")
print("Created components/sepulchria/sep-ui.tsx")
print("Crafting now uses shared SepButton, SepIconButton, SepNotice and SepBadge.")
print("Crafting mechanics and texture treatment were preserved.")
print("Now run: npm run build")
